// Turns the design and catalog sources into code for every consumer:
//   design/tokens.json + design/doodles.json -> Dart (base_design), CSS, Kotlin, Swift, SVG
//   catalog/models.json                      -> Dart (base_models), a JSON copy for non-Flutter apps
import 'dart:convert';
import 'dart:io';

import 'package:path/path.dart' as p;

import 'workspace.dart';

const _header = 'GENERATED by `./base gen` from';

/// Every generated file, keyed by its path relative to the repo root.
Map<String, String> generateAll(Workspace ws) {
  final tokens = ws.readJson('design/tokens.json');
  final doodles = (ws.readJson('design/doodles.json')['doodles'] as Map).cast<String, dynamic>();
  final catalog = ws.readJson('catalog/models.json');
  return {
    'packages/base_design/lib/src/generated/tokens.g.dart': dartTokens(tokens),
    'packages/base_design/lib/src/generated/doodles.g.dart': dartDoodles(doodles),
    'packages/base_models/lib/src/generated/catalog.g.dart': dartCatalog(catalog),
    'packages/base_models/lib/src/generated/platform.g.dart': dartPlatform(ws),
    'generated/css/base-tokens.css': cssTokens(tokens),
    'generated/kotlin/BaseTokens.kt': kotlinTokens(tokens),
    'generated/swift/BaseTokens.swift': swiftTokens(tokens),
    'generated/catalog/models.json': '${const JsonEncoder.withIndent('  ').convert(catalog)}\n',
    for (final e in doodles.entries) 'generated/svg/doodles/${_kebab(e.key)}.svg': svgDoodle(e.value as Map),
  };
}

/// Writes (or, with [check], compares) every generated file. Returns the stale paths.
List<String> runGen(Workspace ws, {bool check = false}) {
  final stale = <String>[];
  generateAll(ws).forEach((rel, content) {
    final f = File(p.join(ws.root, rel));
    final current = f.existsSync() ? f.readAsStringSync() : null;
    if (current == content) return;
    stale.add(rel);
    if (!check) {
      f.parent.createSync(recursive: true);
      f.writeAsStringSync(content);
    }
  });
  return stale;
}

// ---------------------------------------------------------------- colours

/// Accepts #RRGGBB or #AARRGGBB (alpha first, as Android and Flutter write it).
int argb(String hex) {
  final h = hex.replaceFirst('#', '');
  if (h.length == 6) return 0xFF000000 | int.parse(h, radix: 16);
  if (h.length == 8) return int.parse(h, radix: 16);
  throw FormatException('Bad colour $hex');
}

String _hex8(int v) => '0x${v.toRadixString(16).padLeft(8, '0').toUpperCase()}';

String _css(int v) {
  final a = (v >> 24) & 0xFF, r = (v >> 16) & 0xFF, g = (v >> 8) & 0xFF, b = v & 0xFF;
  if (a == 0xFF) return '#${(v & 0xFFFFFF).toRadixString(16).padLeft(6, '0')}';
  return 'rgba($r, $g, $b, ${(a / 255).toStringAsFixed(2)})';
}

Map<String, int> _palette(Map tokens, String mode) => {
  for (final e in ((tokens['color'] as Map)[mode] as Map).entries) e.key as String: argb((e.value as Map)['value'] as String),
};

List<int> _series(Map tokens) => [for (final c in (tokens['color'] as Map)['series'] as List) argb(c as String)];

String _num(Object? n) {
  if (n == null) return 'null';
  final d = (n as num).toDouble();
  return d == d.roundToDouble() ? d.toStringAsFixed(1) : d.toString();
}

String _kebab(String camel) => camel.replaceAllMapped(RegExp('[A-Z]'), (m) => '-${m[0]!.toLowerCase()}');

String _q(String s) => "'${s.replaceAll(r'\', r'\\').replaceAll("'", r"\'").replaceAll(r'$', r'\$')}'";

// ---------------------------------------------------------------- Dart

String dartTokens(Map t) {
  final b = StringBuffer()
    ..writeln('// $_header design/tokens.json. Do not edit.')
    ..writeln('// ignore_for_file: public_member_api_docs')
    ..writeln()
    ..writeln("import 'dart:ui';")
    ..writeln()
    ..writeln('const tokensVersion = ${_q(t['version'] as String)};')
    ..writeln();
  for (final mode in ['light', 'dark']) {
    final cls = mode == 'light' ? 'LightTokens' : 'DarkTokens';
    b.writeln('abstract final class $cls {');
    _palette(t, mode).forEach((k, v) => b.writeln('  static const $k = Color(${_hex8(v)});'));
    b.writeln('}\n');
  }
  b
    ..writeln('/// Muted pencil-box tones for charts and legends. Same in light and dark.')
    ..writeln('const seriesTokens = <Color>[${_series(t).map((v) => 'Color(${_hex8(v)})').join(', ')}];')
    ..writeln();
  void doubles(String cls, String key) {
    b.writeln('abstract final class $cls {');
    (t[key] as Map).forEach((k, v) => b.writeln('  static const double $k = ${_num(v)};'));
    b.writeln('}\n');
  }

  doubles('SpaceTokens', 'space');
  doubles('RadiusTokens', 'radius');
  doubles('StrokeTokens', 'stroke');
  doubles('AlphaTokens', 'alpha');
  doubles('ElevationTokens', 'elevation');
  b.writeln('abstract final class MotionTokens {');
  (t['motion'] as Map).forEach((k, v) => b.writeln('  static const $k = Duration(milliseconds: $v);'));
  b.writeln('}\n');

  b
    ..writeln('class TypeToken {')
    ..writeln('  const TypeToken(this.size, this.lineHeight, this.weight, [this.letterSpacing = 0]);')
    ..writeln('  final double size;')
    ..writeln('  final double lineHeight;')
    ..writeln('  final int weight;')
    ..writeln('')
    ..writeln('  /// In em.')
    ..writeln('  final double letterSpacing;')
    ..writeln('}\n');
  for (final group in ['hand', 'body']) {
    final cls = group == 'hand' ? 'HandTypeTokens' : 'BodyTypeTokens';
    b.writeln('abstract final class $cls {');
    ((t['type'] as Map)[group] as Map).forEach((k, v) {
      final m = v as Map;
      final ls = m['letterSpacing'] == null ? '' : ', ${_num(m['letterSpacing'])}';
      b.writeln('  static const $k = TypeToken(${_num(m['size'])}, ${_num(m['lineHeight'])}, ${m['weight']}$ls);');
    });
    b.writeln('}\n');
  }

  final font = t['font'] as Map;
  b
    ..writeln('const handFontFamily = ${_q(font['hand'] as String)};')
    ..writeln()
    ..writeln('class VoiceToken {')
    ..writeln('  const VoiceToken(this.id, this.label, this.note, this.family, this.informality, this.scale);')
    ..writeln('  final String id;')
    ..writeln('  final String label;')
    ..writeln('  final String note;')
    ..writeln('  final String family;')
    ..writeln('')
    ..writeln("  /// Shantell Sans' INFM axis, or null for fonts without it.")
    ..writeln('  final double? informality;')
    ..writeln('  final double scale;')
    ..writeln('}\n')
    ..writeln('const voiceTokens = <VoiceToken>[');
  for (final v in (font['voices'] as List).cast<Map>()) {
    b.writeln(
      '  VoiceToken(${_q(v['id'] as String)}, ${_q(v['label'] as String)}, ${_q(v['note'] as String)}, '
      '${_q(v['family'] as String)}, ${_num(v['informality'])}, ${_num(v['scale'])}),',
    );
  }
  b
    ..writeln('];\n')
    ..writeln('const defaultVoiceId = ${_q(font['defaultVoice'] as String)};');
  return b.toString();
}

String dartDoodles(Map<String, dynamic> doodles) {
  final b = StringBuffer()
    ..writeln('// $_header design/doodles.json. Do not edit.')
    ..writeln('// ignore_for_file: public_member_api_docs')
    ..writeln()
    ..writeln('/// The hand-drawn icon set: loose strokes on a 24x24 grid, slightly off-true on purpose.')
    ..writeln('enum Doodle {');
  for (final e in doodles.entries) {
    final m = e.value as Map;
    final dots = (m['dots'] as List).map((d) => '(${_num((d as List)[0])}, ${_num(d[1])})').join(', ');
    b.writeln('  ${e.key}(${_q(m['d'] as String)}, [$dots]),');
  }
  b
    ..writeln('  ;\n')
    ..writeln('  const Doodle(this.d, this.dots);')
    ..writeln('  final String d;')
    ..writeln('  final List<(double, double)> dots;')
    ..writeln('}');
  return b.toString();
}

String dartCatalog(Map catalog) {
  final b = StringBuffer()
    ..writeln('// $_header catalog/models.json. Do not edit.')
    ..writeln()
    ..writeln("import '../model_spec.dart';")
    ..writeln()
    ..writeln('const catalogVersion = ${catalog['version']};')
    ..writeln()
    ..writeln('const generatedCatalog = <ModelSpec>[');
  String list(Object? l) => '{${((l as List?) ?? const []).map((e) => _q(e as String)).join(', ')}}';
  for (final m in (catalog['models'] as List).cast<Map>()) {
    b
      ..writeln('  ModelSpec(')
      ..writeln('    id: ${_q(m['id'] as String)},')
      ..writeln('    name: ${_q(m['name'] as String)},')
      ..writeln('    family: ${_q(m['family'] as String)},')
      ..writeln('    runtime: ${_q(m['runtime'] as String)},')
      ..writeln('    role: ${_q(m['role'] as String)},')
      ..writeln('    summary: ${_q(m['summary'] as String)},')
      ..writeln('    capabilities: ${list(m['capabilities'])},')
      ..writeln('    license: ${_q(m['license'] as String)},')
      ..writeln('    platforms: ${list(m['platforms'])},');
    if ((m['minRamMb'] ?? 0) != 0) b.writeln('    minRamMb: ${m['minRamMb']},');
    if (m['recommended'] == true) b.writeln('    recommended: true,');
    b.writeln('    source: ModelSource.${m['source']},');
    if (m['approxBytes'] != null) b.writeln('    approxBytes: ${m['approxBytes']},');
    final sdk = m['sdk'] as Map?;
    if (sdk != null) {
      b.writeln('    sdk: SdkRef(${_q(sdk['name'] as String)}, ${_q(sdk['version'] as String)}, ${_q(sdk['key'] as String)}),');
    }
    final files = (m['files'] as List).cast<Map>();
    if (files.isNotEmpty) {
      b.writeln('    files: [');
      for (final f in files) {
        final sha = f['sha256'] == null ? 'null' : _q(f['sha256'] as String);
        b.writeln('      ModelFile(${_q(f['name'] as String)}, ${_q(f['url'] as String)}, sha256: $sha, bytes: ${f['bytes']}),');
      }
      b.writeln('    ],');
    }
    b.writeln('  ),');
  }
  b.writeln('];');
  return b.toString();
}

String dartPlatform(Workspace ws) {
  final vendor = ws.platform['vendor'] as Map;
  final shared = ws.platform['sharedModels'] as Map;
  return '''
// $_header platform.yaml. Do not edit.

/// Where the shared model store lives. Every app built from this repo must
/// agree on these, or they stop sharing models.
abstract final class PlatformConfig {
  static const vendorName = ${_q(vendor['name'] as String)};
  static const vendorId = ${_q(vendor['id'] as String)};
  static const vendorSlug = ${_q(vendor['slug'] as String)};
  static const sharedModelsFolder = ${_q(shared['folder'] as String)};
  static const appleAppGroup = ${_q(shared['appleAppGroup'] as String)};
  static const androidPermission = ${_q(shared['androidPermission'] as String)};
  static const androidDiscoveryAction = ${_q(shared['androidDiscoveryAction'] as String)};
}
''';
}

// ---------------------------------------------------------------- CSS

String cssTokens(Map t) {
  final b = StringBuffer()
    ..writeln('/* $_header design/tokens.json. Do not edit. */')
    ..writeln('/* Light by default; dark follows the OS unless the app sets data-theme. */');
  void vars(String mode) => _palette(t, mode).forEach((k, v) => b.writeln('  --base-${_kebab(k)}: ${_css(v)};'));
  b.writeln(':root {');
  vars('light');
  final series = _series(t);
  for (var i = 0; i < series.length; i++) {
    b.writeln('  --base-series-$i: ${_css(series[i])};');
  }
  for (final group in ['space', 'radius', 'stroke']) {
    (t[group] as Map).forEach((k, v) => b.writeln('  --base-$group-${_kebab(k as String)}: ${v}px;'));
  }
  (t['motion'] as Map).forEach((k, v) => b.writeln('  --base-motion-${_kebab(k as String)}: ${v}ms;'));
  for (final group in ['hand', 'body']) {
    ((t['type'] as Map)[group] as Map).forEach((k, v) {
      final m = v as Map;
      b
        ..writeln('  --base-type-${_kebab(k as String)}-size: ${m['size']}px;')
        ..writeln('  --base-type-${_kebab(k)}-line: ${m['lineHeight']}px;')
        ..writeln('  --base-type-${_kebab(k)}-weight: ${m['weight']};');
    });
  }
  b
    ..writeln("  --base-font-hand: '${(t['font'] as Map)['hand']}', cursive;")
    ..writeln('}')
    ..writeln(':root[data-theme="dark"] {');
  vars('dark');
  b
    ..writeln('}')
    ..writeln('@media (prefers-color-scheme: dark) {')
    ..writeln('  :root:not([data-theme="light"]) {');
  _palette(t, 'dark').forEach((k, v) => b.writeln('    --base-${_kebab(k)}: ${_css(v)};'));
  b
    ..writeln('  }')
    ..writeln('}');
  return b.toString();
}

// ---------------------------------------------------------------- Kotlin / Swift

String kotlinTokens(Map t) {
  final b = StringBuffer()
    ..writeln('// $_header design/tokens.json in baseApp. Do not edit; run `./base sync` there.')
    ..writeln('package base.platform.tokens')
    ..writeln()
    ..writeln('import androidx.compose.ui.graphics.Color')
    ..writeln('import androidx.compose.ui.unit.dp')
    ..writeln('import androidx.compose.ui.unit.sp')
    ..writeln()
    ..writeln('object BaseTokens {')
    ..writeln('    const val VERSION = "${t['version']}"');
  for (final mode in ['light', 'dark']) {
    b.writeln('    object ${mode == 'light' ? 'Light' : 'Dark'} {');
    _palette(t, mode).forEach((k, v) => b.writeln('        val $k = Color(${_hex8(v)})'));
    b.writeln('    }');
  }
  b.writeln('    val series = listOf(${_series(t).map((v) => 'Color(${_hex8(v)})').join(', ')})');
  for (final group in ['space', 'radius', 'stroke']) {
    b.writeln('    object ${group[0].toUpperCase()}${group.substring(1)} {');
    (t[group] as Map).forEach((k, v) => b.writeln('        val $k = ${_num(v)}.dp'));
    b.writeln('    }');
  }
  b.writeln('    object Motion {');
  (t['motion'] as Map).forEach((k, v) => b.writeln('        const val $k = $v'));
  b.writeln('    }');
  for (final group in ['hand', 'body']) {
    b.writeln('    object ${group == 'hand' ? 'Hand' : 'Body'}Type {');
    ((t['type'] as Map)[group] as Map).forEach((k, v) {
      final m = v as Map;
      b.writeln('        val ${k}Size = ${_num(m['size'])}.sp; val ${k}Line = ${_num(m['lineHeight'])}.sp; const val ${k}Weight = ${m['weight']}');
    });
    b.writeln('    }');
  }
  b.writeln('}');
  return b.toString();
}

String swiftTokens(Map t) {
  String color(int v) {
    final a = (v >> 24) & 0xFF, r = (v >> 16) & 0xFF, g = (v >> 8) & 0xFF, bl = v & 0xFF;
    String f(int c) => (c / 255).toStringAsFixed(3);
    return 'Color(.sRGB, red: ${f(r)}, green: ${f(g)}, blue: ${f(bl)}, opacity: ${f(a)})';
  }

  final b = StringBuffer()
    ..writeln('// $_header design/tokens.json in baseApp. Do not edit.')
    ..writeln('// For native iOS/macOS surfaces (widgets, share extensions) that sit beside a Flutter app.')
    ..writeln('import SwiftUI')
    ..writeln()
    ..writeln('public enum BaseTokens {')
    ..writeln('    public static let version = "${t['version']}"');
  for (final mode in ['light', 'dark']) {
    b.writeln('    public enum ${mode == 'light' ? 'Light' : 'Dark'} {');
    _palette(t, mode).forEach((k, v) => b.writeln('        public static let $k = ${color(v)}'));
    b.writeln('    }');
  }
  b.writeln('    public enum Space {');
  (t['space'] as Map).forEach((k, v) => b.writeln('        public static let $k: CGFloat = ${_num(v)}'));
  b
    ..writeln('    }')
    ..writeln('}');
  return b.toString();
}

String svgDoodle(Map m) {
  final dots = (m['dots'] as List)
      .map((d) => '<circle cx="${(d as List)[0]}" cy="${d[1]}" r="1.5" fill="currentColor" stroke="none"/>')
      .join();
  return '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="currentColor" '
      'stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="${m['d']}"/>$dots</svg>\n';
}
